"""Working old behavior; change request adds one new rule."""


def route(kind: str, amount: float) -> str:
    if amount < 0:
        raise ValueError("amount must be non-negative")
    if kind == "partner" and amount >= 5_000:
        return "partner_desk"
    if amount >= 10_000:
        return "senior"
    return "standard"
